"""Validate a supplier SBOM against the CycloneDX schema, record where it
came from, and report how much of it a scanner can match (issue #233).

Usage: sbom.py --input IN.json --output OUT.json --supplier NAME --version V
               --origin supplier-delivered|generated-from-binary [--tool cve-bin-tool]
Runs in a venv with cyclonedx-python-lib[json-validation]. Schema errors
are ::error and exit 1. The metadata gains a sparkgeo:sbom-origin property;
a generated SBOM also names the supplier and version as its component and
records that we authored it, so nobody mistakes it for the vendor's.
Components with neither a purl nor a CPE, or without a version, match no
advisory and are warned about. Prints component-count and unidentified-count
for GITHUB_OUTPUT.
"""

import argparse
import json
import os
import sys
from pathlib import Path

from cyclonedx.schema import SchemaVersion
from cyclonedx.validation.json import JsonStrictValidator


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--input", required=True)
    ap.add_argument("--output", required=True)
    ap.add_argument("--supplier", required=True)
    ap.add_argument("--version", required=True)
    ap.add_argument("--origin", required=True, choices=["supplier-delivered", "generated-from-binary"])
    ap.add_argument("--tool", default="")
    args = ap.parse_args()

    text = Path(args.input).read_text()
    bom = json.loads(text)
    if bom.get("bomFormat") != "CycloneDX":
        sys.exit(f"::error title=supplier-sbom::{args.input} is not CycloneDX JSON (bomFormat missing)")
    spec = str(bom.get("specVersion", ""))
    schema = getattr(SchemaVersion, "V" + spec.replace(".", "_"), None)
    if schema is None:
        sys.exit(f"::error title=supplier-sbom::unsupported CycloneDX specVersion '{spec}'")
    error = JsonStrictValidator(schema).validate_str(text)
    if error is not None:
        sys.exit(f"::error title=supplier-sbom::{args.input} fails the CycloneDX {spec} schema: "
                 f"{getattr(error.data, 'message', error)}")

    meta = bom.setdefault("metadata", {})
    props = [p for p in meta.get("properties", []) if p.get("name") != "sparkgeo:sbom-origin"]
    meta["properties"] = props + [{"name": "sparkgeo:sbom-origin", "value": args.origin}]
    meta.setdefault("supplier", {"name": args.supplier})
    if args.origin == "generated-from-binary":
        meta["component"] = {"type": "application", "bom-ref": "supplier-delivery", "name": args.supplier,
                             "version": args.version,
                             "description": f"Generated by us from the delivered binary with {args.tool}; "
                                            "not an SBOM from the supplier"}
        meta["authors"] = [{"name": f"{os.environ.get('GITHUB_REPOSITORY', 'sparkgeo')} CI"}]

    components, unidentified = [], []

    def walk(items):
        for c in items or []:
            components.append(c)
            if not c.get("version") or not (c.get("purl") or c.get("cpe")):
                unidentified.append(c.get("name") or c.get("bom-ref") or "(unnamed)")
            walk(c.get("components"))

    walk(bom.get("components"))
    if not components:
        print(f"::warning title=supplier-sbom::{args.supplier} {args.version}: the SBOM lists no components", file=sys.stderr)
    if unidentified:
        print(f"::warning title=supplier-sbom::{len(unidentified)} of {len(components)} component(s) lack a version or "
              f"a purl/CPE and will match no advisory: {', '.join(unidentified[:10])}", file=sys.stderr)
    Path(args.output).write_text(json.dumps(bom, indent=2))

    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as handle:
            handle.write(f"### Supplier SBOM: {args.supplier} {args.version}\n\n"
                         f"Origin: {args.origin}; CycloneDX {spec}; {len(components)} component(s), "
                         f"{len(unidentified)} without a version or purl/CPE.\n")
    print(f"component-count={len(components)}")
    print(f"unidentified-count={len(unidentified)}")


if __name__ == "__main__":
    main()
